class Fenwick {
  final List<int> t;
  Fenwick(int n) : t = List.filled(n + 1, 0);

  void add(int i, int d) {
    for (i++; i < t.length; i += i & -i) {
      t[i] += d;
    }
  }

  int prefix(int i) {
    var s = 0;
    for (i++; i > 0; i -= i & -i) {
      s += t[i];
    }
    return s;
  }

  int range(int l, int r) => prefix(r) - (l > 0 ? prefix(l - 1) : 0);
}

