List<int> smallerRight(List<int> a) {
  final mx = a.reduce((x, y) => x > y ? x : y);
  final f = Fenwick(mx + 1);
  final res = List<int>.filled(a.length, 0);
  for (var i = a.length - 1; i >= 0; i--) {
    res[i] = a[i] > 0 ? f.prefix(a[i] - 1) : 0;
    f.add(a[i], 1);
  }
  return res;
}

void main() {
  print(smallerRight([3, 1, 2, 0]));
}
